668: 		const baseBStar = keyB.indexOf('*');
669: 		const baseLengthB = baseBStar === -1 ? keyB.length : baseBStar + 1;
670: 		// 5. If baseLengthA is greater than baseLengthB, return -1.
671: 		if (baseLengthA > baseLengthB) return -1;
672: 		// 6. If baseLengthB is greater than baseLengthA, return 1.
673: 		if (baseLengthB > baseLengthA) return 1;
674: 		// 7. If keyA does not contain "*", return 1.
675: 		if (baseAStar === -1) return 1;
676: 		// 8. If keyB does not contain "*", return -1.
677: 		if (baseBStar === -1) return -1;
678: 		// 9. If the length of keyA is greater than the length of keyB, return -1.
679: 		if (keyA.length > keyB.length) return -1;
680: 		// 10. If the length of keyB is greater than the length of keyA, return 1.
